import streamlit as st
def header(title, subtitle): st.markdown(f'<div class="eyebrow">QUEUE MIND / OPERATIONS</div><div class="page-title">{title}</div><div class="subtle">{subtitle}</div>',unsafe_allow_html=True)
def metric(label,value,detail): st.markdown(f'<div class="card"><div class="metric-label">{label}</div><div class="metric-value">{value}</div><div class="metric-detail">{detail}</div></div>',unsafe_allow_html=True)
def action_card(status, message, recommendation): st.markdown(f'<div class="card"><div class="metric-label">ACTION CENTER</div><div class="status {status}">{status.upper()} RISK</div><p>{message}</p><div class="metric-detail">{recommendation}</div></div>',unsafe_allow_html=True)
def impact_row(item, status, current, recommended, max_queue, max_wait):
    queue_width=round(100*item["future_queue"]/max(max_queue,1)); wait_width=round(100*item["predicted_wait_minutes"]/max(max_wait,1)); style="current" if current else "recommended" if recommended else ""; color={"critical":"DC4C4C","warning":"D89B2B"}.get(status,"2E9F6B"); label="RECOMMENDED" if recommended else status.upper()
    return f'<div class="impact-row {style}"><div style="display:grid;grid-template-columns:1fr 2fr 2fr 1fr;gap:14px;align-items:center"><div><b>{item["active_counters"]}</b> counters<br><span class="metric-detail">capacity</span></div><div><span class="metric-label">PREDICTED QUEUE</span><div class="bar"><div class="fill" style="width:{queue_width}%;background:#{color}"></div></div><b>{item["future_queue"]:.1f} people</b></div><div><span class="metric-label">PREDICTED WAIT</span><div class="bar"><div class="fill" style="width:{wait_width}%;background:#{color}"></div></div><b>{item["predicted_wait_minutes"]:.1f} min</b></div><div><span class="pill {status}">{label}</span></div></div></div>'
